:root{
  --bg:#06030d;
  --bg2:#120826;
  --ink:#f6efff;
  --dim:#9d8cc4;
  --cyan:#4ff0ff;
  --pink:#ff4fd8;
  --violet:#8b5cff;
  --amber:#ffd166;
  --lime:#a6ff4d;
  --danger:#ff3b6b;
  --lane0:#38e8ff;
  --lane1:#ff54d8;
  --lane2:#ffc94d;
  --lane3:#7dff8a;
  --panel:rgba(19,10,38,.72);
  --panel-solid:#160b2a;
  --line:rgba(151,113,255,.28);
  --font:"Inter","Helvetica Neue",system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;
  --mono:"SF Mono",ui-monospace,"Roboto Mono",Menlo,Consolas,monospace;
}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{height:100%;margin:0}
html{background:var(--bg)}
body{
  overflow:hidden;
  background:var(--bg);
  color:var(--ink);
  font-family:var(--font);
  overscroll-behavior:none;
  touch-action:manipulation;
  -webkit-user-select:none;user-select:none;
  -webkit-font-smoothing:antialiased;
}
button{font-family:inherit;color:inherit;border:0;background:none;cursor:pointer}
button:focus-visible{outline:2px solid var(--cyan);outline-offset:3px}
.hidden{display:none !important}
kbd{
  font-family:var(--mono);font-size:.78em;padding:.1em .42em;border-radius:5px;
  border:1px solid rgba(255,255,255,.22);background:rgba(255,255,255,.07);
}

/* ---------- animated backdrop ---------- */
#backdrop{position:fixed;inset:0;overflow:hidden;pointer-events:none;background:
  radial-gradient(120% 80% at 50% 104%, #2a0f4c 0%, #120725 38%, #06030d 74%),
  linear-gradient(#06030d,#0a0418 60%,#140827);
}
#bgCanvas{position:absolute;inset:0;width:100%;height:100%}
.bg-glow{position:absolute;left:50%;top:32%;width:min(1100px,150vw);height:min(1100px,150vw);transform:translate(-50%,-50%);
  background:radial-gradient(circle,rgba(139,92,255,.20),rgba(255,79,216,.07) 40%,transparent 66%);filter:blur(10px)}
.bg-sun{
  position:absolute;left:50%;bottom:16%;width:min(52vw,420px);aspect-ratio:1;transform:translateX(-50%);
  border-radius:50%;
  background:linear-gradient(180deg,#ffd166 0%,#ff7a59 34%,#ff4fd8 64%,#8b5cff 100%);
  opacity:.16;filter:blur(.5px);
  mask-image:repeating-linear-gradient(180deg,#000 0 7px,transparent 7px 12px);
  -webkit-mask-image:repeating-linear-gradient(180deg,#000 0 7px,transparent 7px 12px);
}
.bg-grid{
  position:absolute;left:-20%;right:-20%;bottom:-14%;height:52%;
  background-image:linear-gradient(rgba(79,240,255,.13) 1px,transparent 1px),linear-gradient(90deg,rgba(255,79,216,.11) 1px,transparent 1px);
  background-size:100% 42px,58px 100%;
  transform:perspective(420px) rotateX(64deg);
  transform-origin:50% 100%;
  mask-image:linear-gradient(transparent,#000 42%,#000);
  -webkit-mask-image:linear-gradient(transparent,#000 42%,#000);
  opacity:.55;
}
.bg-scan{position:absolute;inset:0;background:repeating-linear-gradient(180deg,rgba(255,255,255,.024) 0 1px,transparent 1px 3px);mix-blend-mode:overlay;opacity:.5}

/* ---------- app / screens ---------- */
#app{position:fixed;inset:0;z-index:2}
.screen{position:absolute;inset:0;display:none;flex-direction:column;min-height:0}
.screen.active{display:flex}
.screen.menu{overflow-y:auto;-webkit-overflow-scrolling:touch;touch-action:pan-y}

/* ---------- shared bits ---------- */
.kicker{
  display:flex;align-items:center;gap:.55em;
  font-family:var(--mono);font-size:clamp(9px,1.5vw,11px);letter-spacing:.26em;text-transform:uppercase;color:var(--dim);
}
.kicker .dot{width:6px;height:6px;border-radius:50%;background:var(--cyan);box-shadow:0 0 10px var(--cyan);animation:pulse-dot 1.6s ease-in-out infinite}
.kicker.danger{color:var(--danger)}
.kicker.danger .dot{background:var(--danger);box-shadow:0 0 10px var(--danger)}
@keyframes pulse-dot{50%{opacity:.32;transform:scale(.7)}}

.btn{
  position:relative;display:inline-flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;
  padding:15px 34px;border-radius:14px;font-weight:800;font-size:15px;letter-spacing:.16em;text-transform:uppercase;
  transition:transform .12s ease,box-shadow .18s ease,background .18s ease,border-color .18s;
  min-height:52px;
}
.btn small{font-family:var(--mono);font-size:8.5px;letter-spacing:.3em;opacity:.66;font-weight:500}
.btn.primary{
  color:#0a0416;
  background:linear-gradient(100deg,var(--cyan),#b7a4ff 46%,var(--pink));
  box-shadow:0 0 0 1px rgba(255,255,255,.22) inset,0 8px 32px rgba(255,79,216,.34),0 0 32px rgba(79,240,255,.2);
  clip-path:polygon(10px 0,100% 0,100% calc(100% - 10px),calc(100% - 10px) 100%,0 100%,0 10px);
}
.btn.primary:hover{transform:translateY(-2px);box-shadow:0 0 0 1px rgba(255,255,255,.3) inset,0 12px 40px rgba(255,79,216,.46),0 0 44px rgba(79,240,255,.3)}
.btn.primary:active{transform:translateY(1px) scale(.985)}
.btn.primary[disabled]{opacity:.34;filter:saturate(.3);pointer-events:none}
.btn.ghost{border:1px solid rgba(155,125,255,.34);background:rgba(28,15,54,.52);color:#d9ccff;backdrop-filter:blur(8px)}
.btn.ghost:hover{border-color:rgba(79,240,255,.5);background:rgba(40,22,74,.7)}
.btn.xl{padding:19px 46px;font-size:17px;letter-spacing:.2em}
.danger-text{color:#ff96ad !important}

/* ---------- TITLE ---------- */
.title{
  padding:calc(18px + env(safe-area-inset-top)) calc(20px + env(safe-area-inset-right)) calc(16px + env(safe-area-inset-bottom)) calc(20px + env(safe-area-inset-left));
  justify-content:space-between;gap:18px;
}
.title-top{display:flex;justify-content:center}
.title-main{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:clamp(14px,3.4vh,30px);min-height:0;padding:8px 0}
.logo-wrap{display:flex;flex-direction:column;align-items:center;gap:10px}
.logo-eq{display:flex;align-items:flex-end;gap:5px;height:34px;margin-bottom:2px}
.logo-eq i{
  display:block;width:4px;border-radius:2px;background:linear-gradient(var(--cyan),var(--pink));
  box-shadow:0 0 10px rgba(79,240,255,.6);animation:eq 1.1s ease-in-out infinite;opacity:.9;
}
.logo-eq i:nth-child(1){height:10px;animation-delay:-.1s}
.logo-eq i:nth-child(2){height:22px;animation-delay:-.55s}
.logo-eq i:nth-child(3){height:14px;animation-delay:-.25s}
.logo-eq i:nth-child(4){height:30px;animation-delay:-.8s}
.logo-eq i:nth-child(5){height:18px;animation-delay:-.4s}
.logo-eq i:nth-child(6){height:34px;animation-delay:-.95s}
.logo-eq i:nth-child(7){height:16px;animation-delay:-.15s}
.logo-eq i:nth-child(8){height:26px;animation-delay:-.7s}
.logo-eq i:nth-child(9){height:12px;animation-delay:-.3s}
.logo-eq i:nth-child(10){height:28px;animation-delay:-.85s}
.logo-eq i:nth-child(11){height:9px;animation-delay:-.5s}
@keyframes eq{0%,100%{transform:scaleY(.55)}50%{transform:scaleY(1)}}

.logo{
  margin:0;font-size:clamp(58px,17.5vw,148px);line-height:.82;font-weight:900;
  letter-spacing:-.045em;font-style:italic;
  color:#fff;
  text-shadow:0 0 3px #fff,0 0 22px rgba(79,240,255,.35),0 10px 40px rgba(139,92,255,.55);
  position:relative;
}
.logo span{
  background:linear-gradient(172deg,#fff 4%,var(--cyan) 34%,var(--violet) 58%,var(--pink) 88%);
  -webkit-background-clip:text;background-clip:text;color:transparent;
  filter:drop-shadow(0 0 18px rgba(255,79,216,.38));
}
.logo::after{
  content:"BEATFALL";position:absolute;left:2px;right:0;top:0;z-index:-1;
  color:transparent;-webkit-text-stroke:1px rgba(255,79,216,.24);transform:translate(7px,8px);
}
.logo-rule{display:flex;align-items:center;gap:12px;width:min(360px,84vw);color:var(--dim)}
.logo-rule span{height:1px;flex:1;background:linear-gradient(90deg,transparent,rgba(151,113,255,.5))}
.logo-rule span:last-child{background:linear-gradient(90deg,rgba(151,113,255,.5),transparent)}
.logo-rule b{font-family:var(--mono);font-size:9px;font-weight:500;letter-spacing:.24em;white-space:nowrap}
.tagline{
  margin:0;text-align:center;color:#c5b5e8;font-size:clamp(13px,2.4vw,16px);line-height:1.55;font-weight:500;
  max-width:34em;
}
.tagline br.wide-only{display:none}
.title-actions{display:flex;flex-direction:column;align-items:center;gap:12px;width:min(340px,90vw)}
.title-actions .btn{width:100%}
.best-row{
  display:flex;align-items:center;gap:22px;margin-top:2px;
  font-family:var(--mono);font-size:10px;letter-spacing:.18em;color:var(--dim);
}
.best-row > div{display:flex;flex-direction:column;align-items:center;gap:5px}
.best-row b{font-family:var(--font);font-size:19px;letter-spacing:.04em;color:#fff;font-weight:800}
.best-row .sep{width:1px;height:26px;background:rgba(151,113,255,.34)}
.title-bottom{display:flex;justify-content:center}
.tip{font-family:var(--mono);font-size:9px;letter-spacing:.17em;color:rgba(180,160,220,.55);text-align:center;line-height:1.7;max-width:640px}

/* ---------- BATTLE ---------- */
.battle{
  padding:calc(8px + env(safe-area-inset-top)) calc(10px + env(safe-area-inset-right)) calc(8px + env(safe-area-inset-bottom)) calc(10px + env(safe-area-inset-left));
  gap:6px;touch-action:none;
}
.hud-top{
  display:flex;align-items:center;gap:10px;width:100%;max-width:660px;margin:0 auto;
  padding:9px 11px;border-radius:14px;background:var(--panel);border:1px solid var(--line);
  backdrop-filter:blur(12px);box-shadow:0 8px 30px rgba(0,0,0,.35);
}
.depth-chip{display:flex;flex-direction:column;align-items:center;gap:1px;padding-right:10px;border-right:1px solid rgba(151,113,255,.24);min-width:48px}
.depth-chip .label{font-family:var(--mono);font-size:7.5px;letter-spacing:.2em;color:var(--dim)}
.depth-chip b{font-size:21px;line-height:1;font-weight:900;color:var(--cyan);text-shadow:0 0 14px rgba(79,240,255,.5)}
.vitals{flex:1;display:flex;flex-direction:column;gap:5px;min-width:0}
.hp-line{display:flex;align-items:center;gap:8px}
.hp-bar{position:relative;flex:1;height:8px;border-radius:6px;background:rgba(255,255,255,.08);overflow:hidden}
.hp-bar #hpFill{position:absolute;inset:0;width:100%;transform-origin:left;background:linear-gradient(90deg,var(--lime),var(--cyan));box-shadow:0 0 12px rgba(79,240,255,.6);transition:transform .18s ease}
.hp-ghost{position:absolute;inset:0;width:100%;background:rgba(255,59,107,.5);transform-origin:left;transition:transform .6s .25s ease}
.hp-num{font-family:var(--mono);font-size:10px;letter-spacing:.05em;color:#dffbff;min-width:26px;text-align:right}
.shield-num{font-family:var(--mono);font-size:10px;color:var(--amber);min-width:38px;text-align:right;text-shadow:0 0 8px rgba(255,209,102,.5)}
.vitals-sub{display:flex;align-items:center;justify-content:space-between;font-family:var(--mono);font-size:8px;letter-spacing:.14em;color:var(--dim)}
.attack-status{color:var(--dim);transition:color .2s}
.attack-status.warn{color:var(--danger);animation:blink .45s steps(2,end) infinite}
@keyframes blink{50%{opacity:.3}}
.score-box{display:flex;flex-direction:column;align-items:flex-end;gap:1px;min-width:56px}
.score-box .label{font-family:var(--mono);font-size:7.5px;letter-spacing:.2em;color:var(--dim)}
.score-box b{font-family:var(--mono);font-size:15px;letter-spacing:.02em;font-weight:600;color:#fff}
.icon-btn{
  width:34px;height:34px;border-radius:10px;border:1px solid rgba(151,113,255,.3);background:rgba(255,255,255,.04);
  display:flex;align-items:center;justify-content:center;gap:4px;flex:0 0 auto;
}
.icon-btn span{width:3px;height:12px;border-radius:2px;background:#cbb6ff}
.icon-btn:hover{background:rgba(255,255,255,.1)}

.enemy-panel{width:100%;max-width:660px;margin:0 auto;padding:0 4px;display:flex;flex-direction:column;gap:5px}
.enemy-row{display:flex;align-items:center;gap:8px;padding:0 4px}
.enemy-name{font-weight:900;font-size:clamp(13px,2.6vw,16px);letter-spacing:.16em;color:#fff;text-shadow:0 0 16px rgba(255,79,216,.35);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.boss-tag{font-family:var(--mono);font-size:7.5px;letter-spacing:.18em;padding:2px 6px;border-radius:4px;background:rgba(255,59,107,.16);border:1px solid rgba(255,59,107,.5);color:#ff8aa8}
.enemy-hp{margin-left:auto;font-family:var(--mono);font-size:9px;letter-spacing:.1em;color:var(--dim);white-space:nowrap}
.enemy-bar{position:relative;height:11px;border-radius:5px;background:rgba(255,255,255,.06);border:1px solid rgba(255,79,216,.16);overflow:hidden}
#enemyFill{position:absolute;inset:0;width:100%;transform-origin:left;background:linear-gradient(90deg,#ff2e6d,#ff4fd8 48%,#b06bff);box-shadow:0 0 18px rgba(255,79,216,.55);transition:transform .22s cubic-bezier(.2,.8,.2,1)}
.bar-sheen{position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent 0 38px,rgba(0,0,0,.3) 38px 40px)}

.stage{position:relative;flex:1;min-height:0;width:100%;max-width:660px;margin:0 auto;border-radius:18px;overflow:hidden;
  background:
    radial-gradient(90% 46% at 50% 0%,rgba(255,79,216,.09),transparent 70%),
    linear-gradient(180deg,rgba(18,9,38,.5),rgba(9,4,22,.72));
  border:1px solid rgba(151,113,255,.16);
  box-shadow:inset 0 0 60px rgba(0,0,0,.5),0 20px 60px rgba(0,0,0,.4);
  touch-action:none;
}
#gameCanvas{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}
.coach{
  position:absolute;left:50%;top:12%;transform:translateX(-50%);
  padding:7px 13px;border-radius:8px;background:rgba(8,3,20,.72);border:1px solid rgba(79,240,255,.32);
  font-family:var(--mono);font-size:9px;letter-spacing:.16em;color:#bff7ff;white-space:nowrap;
  opacity:0;transition:opacity .35s;pointer-events:none;text-align:center;
}
.coach.show{opacity:1}
.fever-banner{
  position:absolute;left:50%;top:46%;transform:translate(-50%,-50%) rotate(-3deg);
  font-family:var(--mono);font-size:14px;letter-spacing:.32em;color:#fff;text-shadow:0 0 20px #ff4fd8;
  background:rgba(255,79,216,.12);border-top:1px solid rgba(255,79,216,.6);border-bottom:1px solid rgba(255,79,216,.6);
  padding:6px 18px;opacity:0;transition:opacity .3s;pointer-events:none;white-space:nowrap;
}
.fever-banner.show{opacity:1;animation:feverflick 1s infinite}
@keyframes feverflick{50%{opacity:.55}}

.hud-bottom{
  width:100%;max-width:660px;margin:0 auto;display:flex;align-items:center;gap:12px;
  padding:4px 4px 0;
}
.lane-hints{display:flex;gap:5px}
.lane-hints span{
  width:25px;height:25px;border-radius:6px;display:flex;align-items:center;justify-content:center;
