117:     this._raf = requestAnimationFrame(this._tick);
118:   }
119: 
120:   // ---------- lifecycle ----------
121:   start() {
122:     this._startTime = this.audio.startTrack(this.chart.bpm, this.chart.depth);
123:     this.run.notesTotal += this.notes.length;
124:     this.emitHud(true);
125:   }
126: 
127:   resize() {
128:     const el = this.canvas;
129:     const rect = el.getBoundingClientRect();
130:     const dpr = Math.min(2, window.devicePixelRatio || 1);
131:     this.W = Math.max(200, rect.width);
132:     this.H = Math.max(220, rect.height);
133:     el.width = Math.round(this.W * dpr);
134:     el.height = Math.round(this.H * dpr);
135:     this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
136:     this.pad = Math.max(6, this.W * 0.018);
