144:     this.coreY = Math.min(this.H * 0.18, 96);
145:     this.coreR = Math.min(this.laneW * 0.72, this.H * 0.17, 60);
146:     this.ui = clamp(Math.min(this.W / 390, this.H / 640), 0.72, 1.5);
147:     this.judgeOffset = clamp(this.H * 0.09, 24, 66);
148:     this.comboOffset = clamp(this.H * 0.21, 50, 140);
149:   }
150: 
151:   songTime() {
152:     if (!this._startTime) return 0;
153:     return Math.max(0, this.audio.now() - this._startTime);
154:   }
155: 
156:   destroy() {
157:     cancelAnimationFrame(this._raf);
158:     this._unbindInput();
159:     try { this.ro.disconnect(); } catch { /* */ }
160:     this.audio.stopTrack(0.25);
161:   }
162: 
163:   pause() {
164:     if (this.paused || this.state === 'victory' || this.state === 'defeat') return;
165:     this.paused = true;
166:     this.audio.pause();
167:   }
168:   resume() {
169:     if (!this.paused) return;
170:     this.paused = false;
171:     this.audio.resume();
172:     this._lastTs = 0;
173:   }
174: 
175:   // ---------- input ----------
176:   _bindInput() {
177:     this._onPointerDown = (e) => {
178:       if (this.paused) return;
179:       const rect = this.canvas.getBoundingClientRect();
180:       const x = (e.clientX - rect.left) * (this.W / rect.width);
181:       const lane = Math.floor((x - this.x0) / this.laneW);
182:       if (lane < 0 || lane >= LANES) return;
183:       e.preventDefault();
184:       this.pointers.set(e.pointerId, lane);
185:       this.laneHold[lane]++;
186:       this.pressLane(lane);
187:     };
188:     this._onPointerUp = (e) => {
189:       const lane = this.pointers.get(e.pointerId);
190:       if (lane == null) return;
191:       this.pointers.delete(e.pointerId);
192:       this.laneHold[lane] = Math.max(0, this.laneHold[lane] - 1);
193:     };
194:     this._onKeyDown = (e) => {
195:       if (e.repeat) return;
196:       const key = e.key.toLowerCase();
197:       const lane = { d: 0, f: 1, j: 2, k: 3, arrowleft: 0, arrowup: 1, arrowdown: 2, arrowright: 3 }[key];
198:       if (lane != null) {
199:         e.preventDefault();
200:         if (this.keys.has(key)) return;
201:         this.keys.add(key);
202:         this.keyLane[key] = lane;
