204:         this.pressLane(lane);
205:       } else if (key === ' ' || key === 'shift') {
206:         e.preventDefault();
207:         this.activateFever();
208:       }
209:     };
210:     this._onKeyUp = (e) => {
211:       const key = e.key.toLowerCase();
212:       if (this.keys.has(key)) {
213:         this.keys.delete(key);
214:         const lane = this.keyLane[key];
215:         delete this.keyLane[key];
216:         if (lane != null) this.laneHold[lane] = Math.max(0, this.laneHold[lane] - 1);
217:       }
218:     };
219:     this.pointers = new Map();
220:     this.keys = new Set();
221:     this.keyLane = {};
222:     this.canvas.addEventListener('pointerdown', this._onPointerDown);
223:     window.addEventListener('pointerup', this._onPointerUp);
224:     window.addEventListener('pointercancel', this._onPointerUp);
225:     window.addEventListener('keydown', this._onKeyDown);
226:     window.addEventListener('keyup', this._onKeyUp);
227:   }
228: 
229:   _unbindInput() {
230:     this.canvas.removeEventListener('pointerdown', this._onPointerDown);
231:     window.removeEventListener('pointerup', this._onPointerUp);
232:     window.removeEventListener('pointercancel', this._onPointerUp);
233:     window.removeEventListener('keydown', this._onKeyDown);
234:     window.removeEventListener('keyup', this._onKeyUp);
235:   }
236: 
237:   pressLane(lane) {
238:     if (this.paused || this.state === 'victory' || this.state === 'defeat') return;
239:     this.laneFlash[lane] = 1;
240:     this.pressPulse[lane] = 1;
241:     const t = this.songTime();
242:     const winGood = WIN.good * this.run.windowMult;
243:     let best = null;
244:     let bestDiff = 1e9;
245:     for (const n of this.notes) {
246:       if (n.lane !== lane || n.head !== 'pending') continue;
247:       const d = t - n.time;
248:       if (Math.abs(d) > winGood) continue;
249:       if (Math.abs(d) < Math.abs(bestDiff)) { best = n; bestDiff = d; }
250:     }
251:     if (best) this.judge(best, bestDiff);
252:     else this.audio.ui();
253:   }
254: 
255:   judge(note, diff) {
256:     const wm = this.run.windowMult;
257:     const ad = Math.abs(diff);
258:     let q;
259:     if (ad <= WIN.perfect * wm) q = 0;
260:     else if (ad <= WIN.great * wm) q = 1;
261:     else q = 2;
262: 
263:     note.head = 'hit';
264:     note.quality = q;
265:     note.hitAt = this.songTime();
266: 
267:     this.combo++;
268:     this.maxCombo = Math.max(this.maxCombo, this.combo);
269:     if (this.combo > this.run.bestCombo) this.run.bestCombo = this.combo;
270:     this.comboPop = 1;
271: 
272:     const comboMult = 1 + Math.min(this.combo, this.run.comboCap) * 0.02;
273:     const feverMult = this.feverActive ? this.run.feverDamage : 1;
274:     let dmg = BASE_DAMAGE * TIMING_MULT[q] * comboMult * this.run.damageMult * feverMult;
275:     if (note.hold > 0) dmg *= 1 + 0.12;
276:     this.dealDamage(dmg);
277: 
278:     const feverScore = this.feverActive ? 1.5 : 1;
279:     const addScore = Math.round(100 * TIMING_SCORE[q] * comboMult * feverScore * this.run.scoreMult);
280:     this.score += addScore;
281:     this.run.score += addScore;
282: 
283:     if (!this.feverActive) this.fever = Math.min(100, this.fever + FEVER_GAIN[q] * this.run.feverGain);
284:     this.shield = Math.min(this.run.shieldMax, this.shield + SHIELD_GAIN[q] * this.run.shieldGainMult);
285:     if (this.run.lifesteal > 0) this.hp = Math.min(this.maxHp, this.hp + this.run.lifesteal);
286: 
287:     // stats
288:     this.run.judged++;
289:     this.run.weighted += ACC_WEIGHT[q];
290:     this.run.notesHit++;
291: 
292:     if (note.hold > 0) {
293:       note.nextTick = note.time + this.spb * 0.25;
294:     }
295: 
296:     // juicing
297:     this.audio.hit(q, note.lane);
298:     this.hitGlow = 1;
299:     const x = this.x0 + note.lane * this.laneW + this.laneW / 2;
300:     this.spawnHit(x, this.hitY, note.lane, q);
301:     this.judgeFx = {
302:       text: ['PERFECT', 'GREAT', 'GOOD'][q],
303:       color: q === 0 ? '#bff8ff' : q === 1 ? '#9fe8b3' : '#ffd166',
304:       life: 0, max: 0.5, size: (q === 0 ? 19 : 16) * this.ui
305:     };
306:     this.judgePop = 1;
307:     this.emitHud(true);
308:   }
309: 
310:   dealDamage(dmg) {
311:     if (this.state === 'victory' || this.state === 'defeat') return;
312:     this.enemyHp = Math.max(0, this.enemyHp - dmg);
313:     this.coreFlash = 1;
314:     if (this.enemyHp <= 0) this.victory();
315:   }
