317:   miss(note) {
318:     note.head = 'miss';
319:     this.combo = 0;
320:     this.comboPop = 0;
321:     const dmg = Math.round((6 + this.run.depth * 0.16) * this.run.missMult);
322:     this.hurt(dmg);
