370:     this.result = 'victory';
371:     this.endDelay = 1.6;
372:     const bonus = Math.round((400 + this.run.depth * 120 + this.hp * 6) * this.run.scoreMult);
373:     this.score += bonus;
374:     this.run.score += bonus;
375:     this.clearBonus = bonus;
376:     this.audio.stopTrack(0.7);
377:     this.audio.victory();
378:     this.shake = Math.max(this.shake, 8);
379:     this.feverFlash = 0.8;
380:     for (let i = 0; i < 46; i++) {
381:       const a = Math.random() * Math.PI * 2;
382:       const sp = 60 + Math.random() * 240;
383:       this.particles.push({
384:         x: this.coreX, y: this.coreY,
385:         vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
386:         g: 150, life: 0, max: 0.6 + Math.random() * 0.6,
387:         size: 1.5 + Math.random() * 3,
388:         color: Math.random() < 0.5 ? 'rgba(255,124,228,1)' : 'rgba(110,244,255,1)'
389:       });
390:     }
391:     this.rings.push({ x: this.coreX, y: this.coreY, r: this.coreR, max: Math.max(this.W, this.H) * 0.9, life: 0, dur: 0.75, color: '255,255,255', w: 3 });
392:     this.floaters.push({
393:       text: 'CLEARED', color: '#d8fbff', x: this.W / 2, y: this.H * 0.44,
394:       vy: -14, life: 0, max: 1.4, size: 30 * this.ui
395:     });
396:     this.emitHud(true);
397:   }
398: 
399:   defeat() {
400:     if (this.state === 'defeat' || this.state === 'victory') return;
401:     this.state = 'defeat';
402:     this.result = 'defeat';
403:     this.endDelay = 2;
404:     this.audio.stopTrack(0.4);
405:     this.audio.defeat();
406:     this.shake = Math.max(this.shake, 14);
407:     this.floaters.push({
408:       text: 'FLATLINE', color: '#ff5c7c', x: this.W / 2, y: this.H * 0.44,
409:       vy: -10, life: 0, max: 1.5, size: 26 * this.ui
410:     });
411:     this.emitHud(true);
412:   }
413: 
414:   // ---------- update ----------
415:   update(dt, t) {
416:     this.elapsed += dt;
417:     if (this.state === 'victory' || this.state === 'defeat') {
418:       this.endDelay -= dt;
419:       this.stepEffects(dt);
420:       this.hudTimer += dt;
421:       if (this.hudTimer > 0.12) { this.hudTimer = 0; this.emitHud(); }
422:       if (this.endDelay <= 0 && !this.endCalled) {
423:         this.endCalled = true;
424:         this.finish();
425:       }
426:       return;
427:     }
428: 
429:     if (this.state === 'intro' && t > 0.05) this.state = 'play';
430: 
431:     // fever lifetime
432:     if (this.feverActive && t >= this.feverEnd) {
433:       this.feverActive = false;
434:       this.feverFlash = 0;
435:     }
436: 
437:     // misses
438:     const missCut = WIN.good * this.run.windowMult;
439:     for (const n of this.notes) {
440:       if (n.head !== 'pending') continue;
441:       if (t > n.time + missCut) this.miss(n);
442:     }
443: 
444:     // hold sustain
445:     for (const n of this.notes) {
446:       if (n.head !== 'hit' || n.hold <= 0) continue;
447:       if (this.laneHold[n.lane] <= 0) continue;
448:       const end = n.time + n.hold;
449:       while (n.nextTick > 0 && n.nextTick <= Math.min(t, end)) {
450:         const comboMult = 1 + Math.min(this.combo, this.run.comboCap) * 0.02;
451:         const feverMult = this.feverActive ? this.run.feverDamage : 1;
452:         this.dealDamage(0.9 * this.run.damageMult * comboMult * feverMult * this.run.holdBonus);
453:         const addScore = Math.round(14 * (this.feverActive ? 1.5 : 1) * this.run.scoreMult);
454:         this.score += addScore;
455:         this.run.score += addScore;
456:         n.nextTick += this.spb * 0.25;
457:         n.tickCount++;
458:         if (n.tickCount % 2 === 0) this.audio.tick();
459:         const x = this.x0 + n.lane * this.laneW + this.laneW / 2 + (Math.random() - 0.5) * this.laneW * 0.5;
460:         this.spark(x, this.hitY - 4, n.lane, 2);
461:       }
462:     }
463: 
464:     // enemy attacks
465:     for (const a of this.attacks) {
466:       if (a.fired) continue;
467:       if (t >= a.time) {
468:         a.fired = true;
469:         this.resolveAttack(a);
470:       }
471:     }
472: 
473:     // chart over
474:     const endT = (this.pre + this.chart.totalBeats + 0.5) * this.spb;
475:     if (t > endT && this.state === 'play') this.defeat();
476: 
477:     // coaching hints for the first descent
478:     if (this.run.depth === 1 && this.state === 'play') {
479:       const hints = [
480:         [0.4, 'TAP THE LANES AS NOTES CROSS THE LINE'],
481:         [7.5, 'PERFECTS CHARGE SHIELD ◈ AND FEVER ⚡'],
482:         [16, 'POP FEVER (SPACE / BUTTON) WHEN FULL'],
483:         [24, 'KILL THE TARGET BEFORE THE TRACK ENDS']
484:       ];
485:       const b = t / this.spb;
486:       while (this.hintIndex < hints.length && b > hints[this.hintIndex][0]) {
487:         this.onCoach(hints[this.hintIndex][1], this.hintIndex);
488:         this.hintIndex++;
489:       }
490:     }
491: 
492:     this.stepEffects(dt);
493: 
494:     this.hudTimer += dt;
495:     if (this.hudTimer > 0.1) { this.hudTimer = 0; this.emitHud(); }
496:   }
497: 
498:   resolveAttack(a) {
499:     const dmg = Math.round(a.dmg);
500:     this.shake = Math.max(this.shake, 12);
501:     this.hitGlow = 0.6;
502:     if (this.shield >= dmg) {
503:       this.shield = 0;
504:       this.audio.block();
505:       this.floaters.push({
506:         text: 'BLOCKED', color: '#ffd166', x: this.W / 2, y: this.coreY + this.coreR + 44,
507:         vy: -18, life: 0, max: 0.7, size: 18 * this.ui
508:       });
509:       this.rings.push({ x: this.W / 2, y: this.coreY, r: this.coreR, max: this.coreR * 3.6, life: 0, dur: 0.5, color: '255,209,102', w: 3 });
510:       this.shieldFlash = 1;
511:     } else {
512:       const overflow = dmg - this.shield;
513:       this.shield = 0;
514:       this.hurt(overflow);
515:       this.audio.hurt();
516:       this.hurtFlash = 1;
517:       this.floaters.push({
518:         text: `-${Math.round(overflow * this.run.missMult)} HP`, color: '#ff5c7c', x: this.W / 2, y: this.coreY + this.coreR + 44,
519:         vy: -22, life: 0, max: 0.9, size: 19 * this.ui
520:       });
521:     }
522:     this.emitHud(true);
523:   }
524: 
525:   stepEffects(dt) {
526:     this.laneFlash = this.laneFlash.map(v => Math.max(0, v - dt * 5.5));
527:     this.pressPulse = this.pressPulse.map(v => Math.max(0, v - dt * 7));
528:     this.shake *= Math.pow(0.0018, dt);
529:     this.hurtFlash = Math.max(0, this.hurtFlash - dt * 3.2);
530:     this.feverFlash = Math.max(0, this.feverFlash - dt * 1.5);
531:     this.coreFlash = Math.max(0, this.coreFlash - dt * 5);
532:     this.comboPop = Math.max(0, this.comboPop - dt * 4);
533:     this.judgePop = Math.max(0, this.judgePop - dt * 5);
534:     if (this.judgeFx) {
535:       this.judgeFx.life += dt;
536:       if (this.judgeFx.life >= this.judgeFx.max) this.judgeFx = null;
537:     }
538:     this.hitGlow = Math.max(0, this.hitGlow - dt * 5);
539:     if (this.shieldFlash) this.shieldFlash = Math.max(0, this.shieldFlash - dt * 3);
540: 
541:     for (let i = this.particles.length - 1; i >= 0; i--) {
542:       const p = this.particles[i];
543:       p.life += dt;
544:       if (p.life >= p.max) { this.particles.splice(i, 1); continue; }
545:       p.x += p.vx * dt;
546:       p.y += p.vy * dt;
547:       p.vy += p.g * dt;
548:     }
549:     for (let i = this.rings.length - 1; i >= 0; i--) {
550:       const r = this.rings[i];
551:       r.life += dt;
552:       if (r.life >= r.dur) this.rings.splice(i, 1);
553:     }
554:     for (let i = this.floaters.length - 1; i >= 0; i--) {
555:       const f = this.floaters[i];
556:       f.life += dt;
557:       f.y += f.vy * dt;
558:       if (f.life >= f.max) this.floaters.splice(i, 1);
559:     }
560:     for (const s of this.stars) {
561:       s.y += s.sp * dt;
562:       if (s.y > 1.05) { s.y = -0.05; s.x = Math.random(); }
563:     }
564:   }
565: 
566:   spawnHit(x, y, lane, q) {
567:     const rgb = LANE_RGB[lane];
568:     const count = q === 0 ? 12 : q === 1 ? 8 : 5;
569:     for (let i = 0; i < count; i++) {
570:       const ang = -Math.PI / 2 + (Math.random() - 0.5) * 2.4;
571:       const sp = (60 + Math.random() * 190) * (q === 0 ? 1.25 : 1);
572:       this.particles.push({
573:         x: x + (Math.random() - 0.5) * this.laneW * 0.55,
574:         y: y + (Math.random() - 0.5) * 10,
575:         vx: Math.cos(ang) * sp,
576:         vy: Math.sin(ang) * sp,
577:         g: 280, life: 0, max: 0.34 + Math.random() * 0.3,
578:         size: 1.5 + Math.random() * 2.6,
579:         color: `rgba(${rgb[0]},${rgb[1]},${rgb[2]},1)`
580:       });
581:     }
582:     this.rings.push({
583:       x, y, r: 4, max: this.laneW * 0.72,
584:       life: 0, dur: q === 0 ? 0.34 : 0.28,
585:       color: rgb.join(','), w: q === 0 ? 2.5 : 1.5
586:     });
587:   }
588: 
589:   spark(x, y, lane, count = 3) {
590:     const rgb = LANE_RGB[lane];
591:     for (let i = 0; i < count; i++) {
592:       this.particles.push({
593:         x, y, vx: (Math.random() - 0.5) * 120, vy: -40 - Math.random() * 100,
594:         g: 220, life: 0, max: 0.3 + Math.random() * 0.2,
595:         size: 1 + Math.random() * 1.6,
596:         color: `rgba(${rgb[0]},${rgb[1]},${rgb[2]},1)`
597:       });
598:     }
599:   }
600: 
601:   finish() {
602:     const accuracy = this.run.judged ? this.run.weighted / this.run.judged : 0;
603:     this.run.hp = this.hp;
604:     this.audio.stopTrack(0.2);
605:     this.onEnd(this.result, {
606:       depth: this.run.depth,
607:       score: this.run.score,
608:       battleScore: this.score,
609:       maxCombo: this.maxCombo,
610:       notesHit: this.run.notesHit,
611:       notesTotal: this.run.notesTotal,
612:       accuracy,
613:       hp: this.hp,
614:       clearBonus: this.clearBonus || 0
615:     });
616:   }
617: 
618:   emitHud(force = false) {
619:     const t = this.lastSong;
620:     const next = this.attacks.find(a => !a.fired);
621:     const attackIn = next ? (next.time - t) / this.spb : null;
622:     const snapshot = {
623:       hp: this.hp, maxHp: this.maxHp,
624:       shield: Math.round(this.shield), shieldMax: this.run.shieldMax,
625:       enemyHp: Math.ceil(this.enemyHp), enemyMax: this.enemyMax,
626:       score: this.run.score, combo: this.combo,
627:       mult: 1 + Math.min(this.combo, this.run.comboCap) * 0.02,
628:       fever: this.fever, feverActive: this.feverActive,
629:       feverLeft: this.feverActive ? Math.max(0, this.feverEnd - t) : 0,
630:       attackIn, state: this.state, revives: this.run.revives
631:     };
632:     this.onHud(snapshot);
633:   }
634: 
635:   // ---------- render ----------
636:   _tick = (ts) => {
637:     this._raf = requestAnimationFrame(this._tick);
638:     if (!this._lastTs) this._lastTs = ts;
639:     const dt = Math.min(0.05, (ts - this._lastTs) / 1000);
640:     this._lastTs = ts;
641:     const t = this.songTime();
642:     this.lastSong = t;
643:     if (!this.paused) this.update(dt, t);
644:     else this.stepEffects(dt * 0.3);
645:     this.render(t, dt);
646:   };
647: 
648:   render(t, dt) {
649:     const c = this.ctx;
650:     const W = this.W, H = this.H;
651:     c.clearRect(0, 0, W, H);
652:     c.save();
653:     if (this.shake > 0.4) {
654:       c.translate((Math.random() - 0.5) * this.shake, (Math.random() - 0.5) * this.shake);
655:     }
656: 
657:     const bpmPulse = Math.max(0, 1 - ((t / this.spb) % 1)) ** 2;
658: 
659:     this.drawBg(c, W, H, bpmPulse);
660:     this.drawLanes(c, W, H, t, bpmPulse);
661:     this.drawCore(c, t, bpmPulse);
662:     this.drawNotes(c, t);
663:     this.drawHitLine(c, H, t, bpmPulse);
664:     this.drawParticles(c);
665:     this.drawFloaters(c);
666:     this.drawJudgement(c);
667:     this.drawCombo(c, t);
668: 
669:     if (this.feverActive) {
670:       const left = clamp((this.feverEnd - t) / (this.spb * 8), 0, 1);
671:       const g = c.createLinearGradient(0, 0, 0, H);
672:       g.addColorStop(0, 'rgba(255,79,216,0.14)');
673:       g.addColorStop(0.6, 'rgba(255,79,216,0.03)');
674:       g.addColorStop(1, 'rgba(255,209,102,0.12)');
675:       c.fillStyle = g;
676:       c.fillRect(0, 0, W, H);
677:       c.strokeStyle = `rgba(255,209,102,${0.22 + 0.3 * left})`;
678:       c.lineWidth = 2;
679:       c.strokeRect(1, 1, W - 2, H - 2);
680:       if (this.feverFlash > 0.05) {
681:         c.fillStyle = `rgba(255,255,255,${this.feverFlash * 0.32})`;
682:         c.fillRect(0, 0, W, H);
683:       }
684:     }
685: 
686:     if (this.hurtFlash > 0.02) {
687:       const g = c.createRadialGradient(W / 2, H / 2, H * 0.2, W / 2, H / 2, H * 0.75);
688:       g.addColorStop(0, 'rgba(255,30,80,0)');
689:       g.addColorStop(1, `rgba(255,30,80,${this.hurtFlash * 0.28})`);
690:       c.fillStyle = g;
691:       c.fillRect(0, 0, W, H);
692:     }
693: 
694:     if (this.state !== 'victory' && this.state !== 'defeat' && t < this.spb * 4.9) this.drawCountdown(c, t);
695:     c.restore();
696: 
697:     // vignette (not shaken)
698:     const vg = c.createRadialGradient(W / 2, H * 0.44, H * 0.28, W / 2, H * 0.44, H * 0.92);
699:     vg.addColorStop(0, 'rgba(0,0,0,0)');
700:     vg.addColorStop(1, 'rgba(0,0,0,0.42)');
701:     c.fillStyle = vg;
702:     c.fillRect(0, 0, W, H);
703:   }
704: 
705:   drawBg(c, W, H, pulse) {
706:     const hue = this.chart.hue;
707:     const g = c.createLinearGradient(0, 0, 0, H);
708:     g.addColorStop(0, `hsla(${hue},70%,20%,0.12)`);
709:     g.addColorStop(0.4, 'rgba(10,4,24,0.1)');
710:     g.addColorStop(1, 'rgba(5,2,14,0.34)');
711:     c.fillStyle = g;
712:     c.fillRect(0, 0, W, H);
713: 
714:     // drifting stars
715:     for (const s of this.stars) {
716:       c.globalAlpha = s.a * (0.7 + pulse * 0.3);
717:       c.fillStyle = s.s > 1.4 ? '#ffd9f6' : '#b8e9ff';
718:       c.fillRect(s.x * W, s.y * H, s.s, s.s);
719:     }
720:     c.globalAlpha = 1;
721: 
722:     // side rails
723:     c.strokeStyle = 'rgba(151,113,255,0.16)';
724:     c.lineWidth = 1;
725:     c.beginPath();
726:     c.moveTo(this.x0 - 3, 0);
727:     c.lineTo(this.x0 - 3, H);
728:     c.moveTo(this.x0 + this.playW + 3, 0);
729:     c.lineTo(this.x0 + this.playW + 3, H);
730:     c.stroke();
731:   }
732: 
733:   drawLanes(c, W, H, t, pulse) {
734:     const x0 = this.x0, y0 = 4, y1 = this.hitY + 22;
735:     const fieldH = y1 - y0;
736: 
737:     c.save();
738:     rr(c, x0, y0, this.playW, fieldH, 14);
739:     c.fillStyle = 'rgba(9,4,20,0.48)';
740:     c.fill();
741:     c.clip();
742: 
743:     for (let i = 0; i < LANES; i++) {
744:       const x = x0 + i * this.laneW;
745:       const flash = this.laneFlash[i];
746:       const rgb = LANE_RGB[i];
747:       if (flash > 0.01) {
748:         const lg = c.createLinearGradient(0, this.hitY - 160, 0, this.hitY);
749:         lg.addColorStop(0, `rgba(${rgb[0]},${rgb[1]},${rgb[2]},0)`);
750:         lg.addColorStop(1, `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${0.16 * flash})`);
751:         c.fillStyle = lg;
752:         c.fillRect(x + 1, 0, this.laneW - 2, this.hitY + 20);
753:       }
754:       // beat sheen
755:       const gsheen = c.createLinearGradient(0, 0, 0, this.hitY);
756:       gsheen.addColorStop(0, `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${0.03 + 0.025 * pulse})`);
757:       gsheen.addColorStop(1, 'rgba(0,0,0,0)');
758:       c.fillStyle = gsheen;
759:       c.fillRect(x + 1, 0, this.laneW - 2, this.hitY);
760: 
761:       // lane color rising toward the hit line
762:       const laneGlow = c.createLinearGradient(0, this.hitY - 250, 0, this.hitY);
763:       laneGlow.addColorStop(0, `rgba(${rgb[0]},${rgb[1]},${rgb[2]},0)`);
764:       laneGlow.addColorStop(1, `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${0.055 + flash * 0.03})`);
765:       c.fillStyle = laneGlow;
766:       c.fillRect(x + 1, this.hitY - 250, this.laneW - 2, 250);
767: 
768:       if (i > 0) {
769:         c.strokeStyle = 'rgba(151,113,255,0.13)';
770:         c.lineWidth = 1;
771:         c.beginPath();
772:         c.moveTo(x, 0);
773:         c.lineTo(x, y1);
774:         c.stroke();
775:       }
776:     }
777: 
778:     // horizontal scrolling measure lines
779:     const pxPerBeat = this.pxPerBeat;
780:     const beat = t / this.spb;
781:     const beatFloor = Math.floor(beat);
782:     c.strokeStyle = 'rgba(151,113,255,0.10)';
783:     for (let k = 0; k < 12; k++) {
784:       const b = beatFloor + k - 1;
785:       const y = this.hitY - (b - beat) * pxPerBeat;
786:       if (y < 0 || y > this.hitY + 20) continue;
787:       c.globalAlpha = ((b % 4) === 0 ? 0.5 : 0.22) * clamp(1 - (this.hitY - y) / 500, 0.2, 1);
788:       c.beginPath();
789:       c.moveTo(x0 + 3, y);
790:       c.lineTo(x0 + this.playW - 3, y);
791:       c.stroke();
792:     }
793:     c.globalAlpha = 1;
794: 
795:     // receptors
796:     for (let i = 0; i < LANES; i++) {
797:       const x = x0 + i * this.laneW + (this.laneW - Math.min(this.laneW - 16, 82)) / 2;
798:       const w = Math.min(this.laneW - 16, 82);
799:       const h = 9 + this.pressPulse[i] * 5;
800:       const rgb = LANE_RGB[i];
801:       c.save();
802:       c.shadowColor = `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${0.5 + this.laneFlash[i] * 0.5})`;
803:       c.shadowBlur = 14 + this.laneFlash[i] * 22;
804:       rr(c, x, this.hitY - h / 2, w, h, h / 2);
805:       c.fillStyle = `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${0.18 + this.laneFlash[i] * 0.55})`;
806:       c.fill();
807:       c.strokeStyle = `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${0.55 + this.laneFlash[i] * 0.45})`;
808:       c.lineWidth = 1.5;
809:       c.stroke();
810:       c.restore();
811:     }
812:     c.restore();
813:   }
814: 
815:   drawCore(c, t, pulse) {
816:     const x = this.coreX, y = this.coreY;
817:     const hue = this.chart.hue;
818:     const active = this.state !== 'victory' && this.state !== 'defeat';
819:     const next = this.attacks.find(a => !a.fired);
820:     const warn = next && active && (next.time - t) / this.spb < 2 ? 1 - clamp((next.time - t) / (this.spb * 2), 0, 1) : 0;
821: 
822:     const beat = t / this.spb;
823:     const wob = Math.sin(beat * Math.PI) * 0.03;
824:     const R = this.coreR * (0.94 + pulse * 0.08 + wob) * (this.state === 'victory' ? 0.4 : 1);
825: 
826:     c.save();
827:     c.translate(x, y);
828: 
829:     // aura
830:     const aura = c.createRadialGradient(0, 0, R * 0.2, 0, 0, R * 2.6);
831:     aura.addColorStop(0, `hsla(${hue},90%,65%,${0.26 + pulse * 0.12})`);
832:     aura.addColorStop(0.45, `hsla(${hue},90%,55%,0.09)`);
833:     aura.addColorStop(1, 'hsla(0,0%,0%,0)');
834:     c.fillStyle = aura;
835:     c.beginPath();
