111: export function offerUpgrades(run, depth) {
112:   const rng = mulberry32(hash(run.seed, depth, 0x9e3779b9));
113:   const counts = {};
114:   for (const u of run.upgrades) counts[u.id] = (counts[u.id] || 0) + 1;
115:   const pool = UPGRADES.filter(u => (counts[u.id] || 0) < u.max);
116:   const out = [];
117:   const bag = [...pool];
118:   while (out.length < 3 && bag.length) {
119:     const i = Math.floor(rng() * bag.length);
120:     out.push(bag.splice(i, 1)[0]);
121:   }
122:   // tiny nudge: if none are offensive, swap the last for an offensive option when possible
123:   if (out.length && !out.some(u => u.kind === 'OFFENSE')) {
124:     const alt = bag.find(u => u.kind === 'OFFENSE');
125:     if (alt) out[out.length - 1] = alt;
126:   }
127:   return out;
